def frame(rows: int = 3) -> pl.DataFrame:
    return pl.DataFrame({"player": [f"p{n}" for n in range(rows)], "wins": list(range(rows))})


@pytest.fixture
def session() -> Session:
    made = Session()
    made.namespace["q1"] = frame()
    made.sources["q1"] = "SmashDb console"
    made.namespace["big"] = frame(mentions.WHOLE_ROWS + 1)
    made.namespace["n"] = 5
    return made


def paths(text: str, session: Session) -> list[str]:
    return [mention.path for mention in mentions.find(text, session)]


# -- what counts as a mention ---------------------------------------------------------


def test_only_the_users_variables_are_mentions(session: Session) -> None:
    text = "compare @q1 with @big, mail me@q1.com, @nobody @pl @db @_hidden @@q1 and @q1 again"
    assert paths(text, session) == ["q1", "big"]


def test_a_dotted_path_names_a_column_and_stops_where_the_sentence_goes_on(session: Session) -> None:
    assert paths("@q1.player", session) == ["q1.player"]
    assert isinstance(mentions.find("@q1.player", session)[0].value, pl.Series)
    # "Thanks" is no part of q1: the mention is q1
    assert paths("look at @q1.Thanks", session) == ["q1"]
    assert paths("see @q1.", session) == ["q1"]


def test_a_path_never_calls_or_reaches_private_parts(session: Session) -> None:
    calls = []

    class Thing:
        _secret = 1
        plain = 2

        def method(self) -> int:
            calls.append(1)
            return 3

    session.namespace["thing"] = Thing()
    assert paths("@thing.plain @thing.method @thing._secret", session) == ["thing.plain", "thing"]
    assert not calls


def test_a_console_is_reached_by_its_parts(session: Session) -> None:
    session.namespace["r3"] = DbConsole(session.db, "select 1", frame())
    assert paths("@r3.df @r3.sql", session) == ["r3.df", "r3.sql"]


# -- what the AI gets -----------------------------------------------------------------


def test_a_small_table_goes_whole_with_its_source(session: Session) -> None:
    block = mentions.context("who won most in @q1?", session, tool=True)
    assert "@q1 (made by: SmashDb console)" in block
    assert session.namespace["q1"].write_csv() in block
    assert mentions.TOOL_NAME not in block


def test_a_big_table_is_a_summary_and_names_the_tool_only_where_there_is_one(session: Session) -> None:
    with_tool = mentions.context("@big", session, tool=True)
    assert "Too big to show whole" in with_tool
    assert "player String, wins Int64" in with_tool
    assert f"p{mentions.SAMPLE_ROWS - 1}," in with_tool
    assert f"p{mentions.SAMPLE_ROWS}," not in with_tool
    assert f'{mentions.TOOL_NAME}("big"' in with_tool
    assert mentions.TOOL_NAME not in mentions.context("@big", session, tool=False)


def test_the_threshold_is_whole_rows(session: Session) -> None:
    session.namespace["edge"] = frame(mentions.WHOLE_ROWS)
    assert "all of it as CSV" in mentions.context("@edge", session)
    assert "all of it as CSV" not in mentions.context("@big", session)


def test_other_values_are_described(session: Session) -> None:
    assert "@n (made by: python): int: 5" in mentions.context("@n", session)
    session.namespace["long"] = "x" * (mentions.WHOLE_CHARS * 2)
    assert "(cut: " in mentions.context("@long", session)


def test_a_message_without_mentions_is_sent_as_it_is(session: Session) -> None:
    assert mentions.context("no variables here, a@b.com", session) == ""
    assert mentions.with_context("hello", session) == "hello"
    assert mentions.with_context("hi @q1", session).startswith("hi @q1\n\n")
    assert mentions.context("@q1", None) == ""


# -- only mentions: printed, no AI ------------------------------------------------------


def test_bare_is_a_message_of_nothing_but_mentions(session: Session) -> None:
    assert [mention.path for mention in mentions.bare("@q1", session) or []] == ["q1"]
    assert [mention.path for mention in mentions.bare(" @q1  @big.wins ", session) or []] == ["q1", "big.wins"]
    assert mentions.bare("@q1 who wins?", session) is None
    assert mentions.bare("@nobody", session) is None
    assert mentions.bare("@q1.Thanks", session) is None  # not a part of q1: a normal message
    assert mentions.bare("", session) is None


# -- the list "@" opens -----------------------------------------------------------------


def test_rows_list_the_variables_with_their_parts(session: Session) -> None:
    rows = {row["name"]: row for row in mentions.rows(session)}
    assert list(rows) == ["q1", "big", "n"]
    assert rows["q1"] == {
        "name": "q1",
        "type": "DataFrame",
        "shape": "3 × 2",  # noqa: RUF001  # the app writes shapes with a real multiplication sign
        "source": "SmashDb console",
        "parts": ["player", "wins"],
    }
    assert mentions.rows(None) == []


# -- the chat agent's tool --------------------------------------------------------------


def query(session: Session, name: str, sql: str) -> ds.ai.TableResult:
    return mentions.toolset(session).tools[mentions.TOOL_NAME].function(name, sql)


def test_query_variable_runs_sql_on_the_variable(session: Session) -> None:
    result = query(session, "big", "select count(*) as rows, max(wins) as most from self")
    assert result.to_df().row(0) == (mentions.WHOLE_ROWS + 1, mentions.WHOLE_ROWS)
    assert query(session, "@big.wins", "select sum(wins) as total from self").to_df().height == 1


def test_query_variable_tells_the_model_what_is_wrong(session: Session) -> None:
    with pytest.raises(ModelRetry, match="no variable"):
        query(session, "nope", "select 1")
    with pytest.raises(ModelRetry, match="not a table"):
        query(session, "n", "select 1")
    with pytest.raises(ModelRetry, match="SQL error"):
        query(session, "big", "select missing from self")


def test_a_turn_sends_the_block_and_binds_the_tool_result(session: Session) -> None:
    """Session.ask with what state.send_chat passes: the model gets the message plus the block,
    can call query_variable, and its result is bound as r1 like any tool's table.
    """
    seen: list[str] = []

    async def respond(messages: list[ModelMessage], info: AgentInfo) -> AsyncIterator[str | DeltaToolCalls]:
        returned = [part for part in messages[-1].parts if isinstance(part, ToolReturnPart)]
        if returned:
            yield "done"
            return
        seen.extend(part.content for part in messages[-1].parts if isinstance(part, UserPromptPart))
        assert mentions.TOOL_NAME in [tool.name for tool in info.function_tools]
        args = {"name": "big", "sql": "select * from self order by wins desc limit 2"}
        yield {0: DeltaToolCall(name=mentions.TOOL_NAME, json_args=json.dumps(args))}

    async def on_delta(_: str) -> None:
        return None

    prompt = "top two of @big?"
    with ds.ai.agent.override(model=FunctionModel(stream_function=respond)):
        result = asyncio.run(
            session.ask(
                prompt,
                on_delta,
                sent=mentions.with_context(prompt, session, tool=True),
                toolsets=[mentions.toolset(session)],
            )
        )
    assert not result.error
    assert seen[0].startswith(prompt)
    assert "Too big to show whole" in seen[0]
    assert [step.result_name for step in result.steps] == ["r1"]
    assert session.namespace["r1"]["wins"].to_list() == [mentions.WHOLE_ROWS, mentions.WHOLE_ROWS - 1]


def test_the_form_ai_gets_the_block(session: Session) -> None:
    """A form's inline chat: "@q1" in the instruction puts the variable in its one request."""
    seen: list[str] = []
    form = form_by_key("get_player_usage")

    def respond(messages: list[ModelMessage], info: AgentInfo) -> ModelResponse:
        seen.extend(part.content for part in messages[-1].parts if isinstance(part, UserPromptPart))
        return ModelResponse(parts=[ToolCallPart(info.output_tools[0].name, {"player": "p2", "sets": 30})])

    with inline_fill.fill_agent.override(model=FunctionModel(respond)):
        answer = asyncio.run(inline_fill.fill(session, form, {}, "the player with most wins in @q1"))
    assert not answer.error
    assert session.namespace["q1"].write_csv() in seen[0]


# -- cleared means gone -----------------------------------------------------------------


def test_a_mentioned_variable_is_freed_when_cleared(session: Session) -> None:
    """Mentioning gives the AI text only: no part of mentions.py may keep the object."""
    alive = weakref.ref(session.namespace["big"])
    tools = mentions.toolset(session)
    mentions.with_context("@big @big.wins", session, tool=True)
    mentions.bare("@big", session)
    mentions.rows(session)
    tools.tools[mentions.TOOL_NAME].function("big", "select * from self limit 1")
    session.clear(["big"])
    session.purge()
    gc.collect()
    assert alive() is None
    assert mentions.find("@big", session) == []
